INSERT INTO `blog` (`id`, `name`, `photo`, `des`, `des1`, `slug`, `fld_order`, `actstat`) VALUES
(15, 'REAL ESTATE SALES EXECUTIVE / MANAGER', '140924085117AllOfficeCenters.com-Jobs-and-Career-Hero-Image-7.webp', '<p><strong>Job Description</strong></p>\r\n<p>We are seeking a dynamic Sales/Business Development Manager to lead our sales efforts for a new project. The ideal candidate will have prior experience in Sales/Business Development and Relationship Management with a real estate developer or channel partner in the Delhi/NCR region.</p>\r\n<p>This role provides a unique opportunity to be at the forefront of an emerging real estate company with significant growth potential. The candidate will be instrumental in building and managing relationships with real estate agents, generating leads, and driving sales to achieve ambitious targets. This position includes a competitive compensation package with a substantial upside based on performance.</p>\r\n<p><strong>Role &amp; Responsibilities</strong></p>\r\n<ul>\r\n<li>Develop and maintain strong customer relationships through calls, follow-ups, and site visits.</li>\r\n<li>Engage in cold-calling to generate new business leads and arrange meetings.</li>\r\n<li>Convert real estate agents into channel partners and manage partnerships with prominent real estate agencies to create sales opportunities.</li>\r\n<li>Collaborate with agents, brokers, and channel partners to generate and convert leads into sales.</li>\r\n<li>Independently generate leads from the market and maintain an in-depth knowledge of the local real estate market.</li>\r\n<li>Deliver expert presentations to potential clients and partners.</li>\r\n<li>Meet and exceed sales targets through diligent work and strategic planning.</li>\r\n</ul>\r\n<p><strong>Preferred Candidate Profile</strong></p>\r\n<ul>\r\n<li>Experience working in real estate with a developer in the Delhi/NCR region.</li>\r\n<li>Experience as a Relationship Manager with a real estate developer in the Delhi/NCR region.</li>\r\n<li>Proven experience in real estate sales or sales in other industries.</li>\r\n<li>Strong background in business development, including cold calling and relationship management.</li>\r\n<li>Excellent communication and presentation skills, with fluency in English.</li>\r\n<li>Ability to work independently and as part of a team.</li>\r\n</ul>\r\n<p><strong>Perks and Benefits</strong></p>\r\n<ul>\r\n<li>Sales Commission Plan: Significant portion of total compensation based on performance.</li>\r\n</ul>\r\n<p><strong>Industry Type:</strong> Real Estate<br><strong>Department:</strong> Sales &amp; Business Development<br><strong>Employment Type:</strong> Full-Time, Permanent<br><strong>Role Category:</strong> Enterprise &amp; B2B Sales<br><strong>Education:</strong> Any Graduate</p>', '', 'realestatesalesexecutivemanager', 0, 1),
(16, 'ACCOUNTANT', '', '<p><strong>Job description</strong></p>\r\n<p><strong>Role &amp; responsibilities</strong></p>\r\n<ul>\r\n<li>Bachelor&rsquo;s or Master&rsquo;s in Accounting or Finance.</li>\r\n<li>2+ years of experience as a professional accountant.</li>\r\n<li>Experience of using accounting software.</li>\r\n<li>Knowledge of Indian accounting practices and taxation laws.</li>\r\n<li>Proficiency with computers and MS Office ( Word, Excel, PowerPoint).</li>\r\n<li>Strong written and verbal communication skills.</li>\r\n<li>High level of accuracy, efficiency, honesty, and responsibility.</li>\r\n<li>Motivation and a strong desire to take on new challenges and learn as much as possible.</li>\r\n</ul>\r\n<h3>Accountant Responsibilities</h3>\r\n<ul>\r\n<li>Preparing accounting entries and reconciling general ledgers.</li>\r\n<li>Providing detailed analysis and explanation of transactions.</li>\r\n<li>Working with the company&rsquo;s accounts payable functions &ndash; maintaining invoice payment, ensuring accuracy and timeliness of payments and managing vendor contracts.</li>\r\n<li>Preparing monthly financial and various detailed reports.</li>\r\n<li>Being familiar with Indian companies&rsquo; laws and be able to research and interpret new laws.</li>\r\n<li>Be able to communicate and work with Indian authorities (like IT department, GST Department, etc.) for company-related work.</li>\r\n<li>Work with company CA for compliance-related activities, including but not limited to financial documentation.</li>\r\n<li>Facilitate all statutory audits for the company.</li>\r\n<li>Take on additional tasks or projects to learn more about accounting and office operations.</li>\r\n</ul>', '', 'accountant', 2, 1),
(17, 'DIGITAL MARKETING MANAGER', '', '<p><strong>Objectives of this role</strong></p>\r\n<ul type=\"disc\">\r\n<li>Plan, execute, and manage all digital marketing for A2P REALTECH PVT LTD, including SEO, SEM, email marketing, and social media</li>\r\n<li>Establish and execute a digital marketing strategy to distribute content</li>\r\n<li>Work with and manage a team of writers, marketers, and other others to maintain A2P&rsquo;s digital presence</li>\r\n<li>Maintain consistent brand messaging across all social channels</li>\r\n<li>Identify, analyze, and measure trends and content to assess how well it&rsquo;s performing and optimize user experience</li>\r\n<li>Create and maintain an editorial calendar to deliver targeted content</li>\r\n</ul>\r\n<p><strong>Responsibilities</strong></p>\r\n<ul type=\"disc\">\r\n<li>Create and manage content for A2P&rsquo;s social media, emails, and other forms of digital communication</li>\r\n<li>Research, track, and analyze consumer behaviors and trends and implement research into digital marketing campaigns</li>\r\n<li>Collaborate with the marketing team to brainstorm new and innovative growth strategies and marketing techniques</li>\r\n<li>Develop and monitor campaign budgets</li>\r\n<li>Stay up to date on the latest social media trends, and implement them in A2P&rsquo;s marketing campaigns</li>\r\n</ul>\r\n<p><strong>Skills and qualifications</strong></p>\r\n<ul type=\"disc\">\r\n<li>Social media savvy, with a passion for staying on top of trends</li>\r\n<li>Strong sense of creativity, imagination, and innovation</li>\r\n<li>Excellent interpersonal skills, with the ability to collaborate with other departments</li>\r\n<li>In-depth knowledge of various social media platforms and best practices</li>\r\n<li>Ability to analyze consumer metrics, reports, and trends</li>\r\n<li>Strong project management and managerial skills</li>\r\n</ul>\r\n<p><strong>Preferred qualifications</strong></p>\r\n<ul type=\"disc\">\r\n<li>In-depth knowledge of current digital trends</li>\r\n<li>Experience in digital marketing, or a related field</li>\r\n<li>Proficiency in photo and video editing software</li>\r\n<li>Experience with SEO and SEM strategy and keyword research</li>\r\n<li>Understanding of website analytics tools, such as Google Analytics</li>\r\n<li>Analytical mind, with a passion for measuring data</li>\r\n</ul>', '', 'digitalmarketingmanager', 3, 1),
(18, 'TELE CALLER / Sr. TELE CALLER', '', '<div>\r\n<p><strong>Responsibilities</strong></p>\r\n</div>\r\n<div>\r\n<ul>\r\n<li>Initiate outbound calls to potential clients to promote properties and generate leads.</li>\r\n<li>Respond to inbound calls and answer queries related to various real estate projects.</li>\r\n<li>Schedule and coordinate site visits with potential buyers.</li>\r\n<li>Maintain and update customer records in the CRM system.</li>\r\n<li>Follow up with clients to provide additional information and gather feedback.</li>\r\n<li>Collaborate with the sales team to achieve sales targets and objectives.</li>\r\n<li>Stay updated on real estate market trends and project details.</li>\r\n</ul>\r\n</div>\r\n<div>\r\n<p><strong>Qualifications</strong></p>\r\n</div>\r\n<div>\r\n<ul>\r\n<li>High school diploma or equivalent; a bachelor\'s degree in any field is preferred.</li>\r\n<li>Proven experience in telecalling or telemarketing, preferably in the real estate sector.</li>\r\n<li>Excellent communication and interpersonal skills.</li>\r\n<li>Ability to build rapport with clients and identify potential sales opportunities.</li>\r\n<li>Proficient in using CRM software and other telecalling tools.</li>\r\n<li>Strong organizational and multitasking abilities.</li>\r\n</ul>\r\n</div>\r\n<div>\r\n<p><strong>Skills</strong></p>\r\n</div>\r\n<div>\r\n<ul>\r\n<li>Communication</li>\r\n<li>Telemarketing</li>\r\n<li>Customer Relationship Management (CRM)</li>\r\n<li>Sales Techniques</li>\r\n<li>Real Estate Knowledge</li>\r\n<li>Time Management</li>\r\n<li>Microsoft Office</li>\r\n</ul>\r\n</div>\r\n<p>&nbsp;</p>', '', 'telecallersrtelecaller', 0, 1),
(19, 'REAL ESTATE TEAM LEAD', '', '<p>As a Real Estate Team Lead, you will be responsible for setting sales targets, mentoring and coaching team members, monitoring performance, and implementing strategies to drive team success. You will also be involved in networking and building relationships with clients, ensuring excellent customer service, and staying updated on market trends and competitor activities.</p>\r\n<div>\r\n<p><strong>Responsibilities</strong></p>\r\n</div>\r\n<div>\r\n<ul>\r\n<li>Lead, supervise, and motivate a team of real estate agents</li>\r\n<li>Set sales targets and develop strategies to achieve them</li>\r\n<li>Monitor team performance and provide feedback and coaching to improve results</li>\r\n<li>Assist team members in closing deals and handling complex negotiations</li>\r\n<li>Network and build relationships with clients, industry professionals, and partners</li>\r\n<li>Conduct market research to stay updated on current trends and competitor activities</li>\r\n<li>Ensure outstanding customer service and satisfaction</li>\r\n<li>Review contracts, agreements, and other legal documents</li>\r\n<li>Manage team schedules and ensure efficient workflow</li>\r\n</ul>\r\n</div>\r\n<div>\r\n<p><strong>Qualifications</strong></p>\r\n</div>\r\n<div>\r\n<ul>\r\n<li>Proven experience as a successful real estate agent</li>\r\n<li>Strong leadership and team management skills</li>\r\n<li>Excellent communication and interpersonal skills</li>\r\n<li>Ability to motivate and inspire team members</li>\r\n<li>In-depth knowledge of the local real estate market</li>\r\n<li>Ability to build and maintain relationships with clients and industry professionals</li>\r\n<li>Knowledge of relevant legal regulations and procedures</li>\r\n<li>Strong negotiation and problem-solving skills</li>\r\n<li>Self-motivated and results-oriented</li>\r\n<li>Bachelor\'s degree in a related field (preferred)</li>\r\n</ul>\r\n</div>\r\n<div>\r\n<p><strong>Skills</strong></p>\r\n</div>\r\n<div>\r\n<ul>\r\n<li>Real estate sales</li>\r\n<li>Team leadership</li>\r\n<li>Sales strategy development</li>\r\n<li>Coaching and mentoring</li>\r\n<li>Networking</li>\r\n<li>Client relationship management</li>\r\n<li>Market research</li>\r\n<li>Customer service</li>\r\n<li>Contract review</li>\r\n<li>Negotiation</li>\r\n<li>Problem-solving</li>\r\n<li>Proficiency in relevant software and tools (e.g., CRM, MS Office)</li>\r\n</ul>\r\n</div>\r\n<p>&nbsp;</p>', '', 'realestateteamlead', 0, 1),
(20, '', '', '', '', '', 0, 1);

