CREATE TABLE `subproduct` (
  `id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `photo` varchar(255) NOT NULL,
  `des` longtext NOT NULL,
  `fld_order` int(11) NOT NULL,
  `actstat` int(2) NOT NULL,
  `subcat` int(11) NOT NULL,
  `pcode` varchar(50) NOT NULL,
  `photo2` varchar(400) NOT NULL,
  `photo3` varchar(400) NOT NULL,
  `photo4` varchar(400) NOT NULL,
  `photo5` varchar(400) NOT NULL,
  `photo6` varchar(400) NOT NULL,
  `photo7` varchar(400) NOT NULL,
  `pro_additionalinfo` longtext NOT NULL,
  `pro_shortdes` longtext NOT NULL,
  `pro_discountprice` longtext NOT NULL,
  `pro_mainprice` longtext NOT NULL,
  `pro_specification` longtext NOT NULL,
  `pro_lable` longtext NOT NULL,
  `developer` varchar(255) DEFAULT '',
  `city` varchar(255) DEFAULT '',
  `code` longtext NOT NULL,
  `subcat2` int(11) NOT NULL,
  `meta_title` longtext NOT NULL,
  `meta_keyword` longtext NOT NULL,
  `meta_description` longtext NOT NULL,
